#include <iostream>
#include <vector>

auto datos_validos(const std::vector<int>& datos, int limite) -> bool;
auto seleccionar(const std::vector<int>& datos, int limite) -> std::vector<int>;
auto total(const std::vector<int>& datos) -> int;

int main() {
    std::vector<int> datos;
    int cantidad_entrada{0};
    std::cin >> cantidad_entrada;
    for (int entrada{0}; entrada < cantidad_entrada; ++entrada) {
        int dato{0};
        std::cin >> dato;
        datos.push_back(dato);
    }
    int limite{0};
    std::cin >> limite;
    if (!datos_validos(datos, limite)) {
        std::cout << "Datos invalidos";
        return 0;
    }
    const std::vector<int> elegidos = seleccionar(datos, limite);
    std::cout << "Cantidad:" << elegidos.size() << ";Total:" << total(elegidos) << "\n";
    std::cout << "Seleccion:";
    for (int valor : elegidos) {
        std::cout << "[" << valor << "]";
    }
    std::cout << "\nOriginal:" << datos.size();
    return 0;
}

auto datos_validos(const std::vector<int>& datos, int limite) -> bool {
    if (datos.size() > 8 || limite < 0 || limite > 20) {
        return false;
    }
    for (int valor : datos) {
        if (valor < 0 || valor > 20) {
            return false;
        }
    }
    return true;
}

auto seleccionar(const std::vector<int>& datos, int limite) -> std::vector<int> {
    std::vector<int> resultado;
    for (int valor : datos) {
        if (valor > limite) {
            resultado.push_back(valor);
        }
    }
    return resultado;
}

auto total(const std::vector<int>& datos) -> int {
    int resultado = 0;
    for (int valor : datos) {
        resultado += valor;
    }
    return resultado;
}
